target='......(.((((.((((....(...((((.(....).))))...)))))..((......((((....)))))).)))).).....................'
stack=[]
pairs=[None]*len(target)
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[i]=j; pairs[j]=i
for i in range(len(target)):
    if pairs[i] is not None and i<pairs[i]:
        print(i+1,'-',pairs[i]+1, 'dist', pairs[i]-i)
print('total pairs', sum(1 for p in pairs if p is not None)//2)
print('len', len(target))
